import logging
import sys
from argparse import ArgumentParser, RawTextHelpFormatter
from re import search
from subprocess import PIPE, Popen

from ta_logcollector.help import actions, desc, qtgui, qtgui_a, qtgui_y, reset, start, start_y, stop, stop_y, style
from ta_logcollector.ver import __version__


def run():
    """Function to collect command line arguments and construct main object with correct set of parameters."""
    parser = ArgumentParser(description=desc, formatter_class=RawTextHelpFormatter)
    parser.add_argument("-V", "--version", action="version", version="%(prog)s Version: " + __version__)
    action = parser.add_subparsers(title="action", dest="action", description="Available subcommands", help=actions)
    action_start = action.add_parser(name="start", formatter_class=RawTextHelpFormatter, help=start)
    g1 = action_start.add_mutually_exclusive_group()
    g1.add_argument("-y", "--yamlfile", dest="yamlfile", help=start_y)
    action_stop = action.add_parser(name="stop", formatter_class=RawTextHelpFormatter, help=stop)
    g2 = action_stop.add_mutually_exclusive_group()
    g2.add_argument("-y", "--yamlfile", dest="yamlfile", help=stop_y)
    action_qtgui = action.add_parser(name="qtgui", help=qtgui, formatter_class=RawTextHelpFormatter)
    action_qtgui.add_argument("-style", dest="style", help=style, default="fusion")
    action_qtgui.add_argument("-a", "--autodetect", dest="autodetect", help=qtgui_a, action="store_false")
    action_qtgui.add_argument("-y", "--yamlfile", dest="yamlfile", help=qtgui_y)
    _ = action.add_parser(name="reset", formatter_class=RawTextHelpFormatter, help=reset)
    args = parser.parse_args()

    if args.action == "qtgui":
        try:
            _run_qtgui(args)
        except ImportError:
            if _install_qt_implementation():
                _run_qtgui(args)
        except Exception as exp:
            from traceback import print_exc

            print_exc()
            sys.exit("Please report to i_krk_test_tools@internal.nsn.com with subject: {}".format(exp))
    elif args.action == "start" or args.action == "stop":
        from ta_logcollector.cli import CliInterface, parse_config

        cfg = parse_config(args)
        getattr(CliInterface(), "{}_collecting_logs".format(args.action))(cfg)
    elif args.action == "reset":
        lc_processes = [
            "python",
            "python3",
            "lc_logserver3",
            "lc_server3",
            "logcollector3",
            "logcollector",
        ]
        try:
            _kill_lc_processes(lc_processes)
        except IndexError:
            pass
    else:
        parser.print_help()


def _kill_lc_processes(lc_processes):
    from psutil import process_iter

    for proc in process_iter(["pid", "name", "cmdline"]):
        if proc.name() in lc_processes:
            if proc.cmdline()[1].split("/")[-1:][0] in lc_processes:
                proc.kill()


def _run_qtgui(args):
    # type: (Namespace) -> None
    import signal

    from qtpy import QtCore
    from qtpy.QtWidgets import QApplication

    from ta_logcollector.gui.mainwindow import LogCollector

    # only for py2 with PySide2, py3 with PyQt5/PySide2 are fine
    QtCore.QCoreApplication.setAttribute(QtCore.Qt.AA_ShareOpenGLContexts)
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    signal.signal(signal.SIGINT, signal.SIG_DFL)
    app = QApplication(sys.argv)
    LogCollector(args)
    sys.exit(app.exec_())


def _install_qt_implementation():
    # type: () -> bool
    logger = get_temp_logger()
    result = False
    logger.info(
        "Qt libraries for GUI are missing! We will install it for you, but it can take up to 8 min. "
        "Once it done GUI will start. Please be patient!"
    )
    extras_require = {
        3: ["PyQt5 == 5.14.0", "QtAwesome <= 1.1.1", "QtPy >= 1.5.2, <= 1.11.3"],
    }
    packages = " ".join(['"{}"'.format(package) for package in extras_require[sys.version_info.major]])
    pip_cmd = "pip{py_ver} install -U {packages}".format(py_ver=sys.version_info.major, packages=packages)
    stdout, stderr = Popen([pip_cmd], shell=True, stderr=PIPE, stdout=PIPE).communicate()
    installed_packages = search(r"(Successfully\sinstalled\s.*)", stdout.decode())
    notification = "Can not install Qt packages for LogCollector GUI\n{}\n{}\nRun manually: {}".format(
        stdout.decode(), stderr.decode(), pip_cmd
    )
    if installed_packages:
        notification = "{}".format(installed_packages.group(1))
        result = True
    logger.info(notification)
    return result


def get_temp_logger() -> logging.Logger:
    logger = logging.getLogger("ta_logcollector_cmd")
    logger.setLevel(logging.DEBUG)
    console_handler = logging.StreamHandler()
    console_handler.setLevel(logging.DEBUG)
    logger.addHandler(console_handler)
    return logger


if __name__ == "__main__":
    run()
